head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldbnf90005";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_rowCopy();
        await scwin.init_loadList();
        scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldbnf90005.onpageload' });
    }
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "ipt_method", fn: function () { return String(String((dma_pageContext.get("method") ?? ""))); } },
        { childId: "ipt_itemCd", fn: function () { return String(String((dma_pageContext.get("itemCd") ?? ""))); } },
        { childId: "ipt_itemNm", fn: function () { return String(String((dma_pageContext.get("itemNm") ?? ""))); } },
        { childId: "__rb0", fn: function () { return String(String((dma_pageContext.get("typNm") ?? ""))) + "조회"; } },
        { childId: "ipt_searchWord", fn: function () { return String(String((dma_pageContext.get("searchWord") ?? ""))); } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        (($c.util.getComponent('ipt_searchWord')) && ($c.util.getComponent('ipt_searchWord')).setFocus ? ($c.util.getComponent('ipt_searchWord')).setFocus() : (($c.util.getComponent('ipt_searchWord')) && ($c.util.getComponent('ipt_searchWord')).focus ? ($c.util.getComponent('ipt_searchWord')).focus() : void 0)).select();

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf90005.onpageload' }); }
};

/**
 * @method
 * @name init_loadList
 * @description 초기 목록 조회 — as-is 는 진입 자체가 조회였다
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: reuse_tx). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_fn_searchList();
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name ipt_searchWord_onblur
 * @description ipt_searchWord 포커스 이탈 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ipt_searchWord_onblur = function(e){
    try {
        const ev = e;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        $c.str.replaceAll(selfVar);

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf90005.ipt_searchWord_onblur' }); }
};

/**
 * @method
 * @name btn_searchList_onclick
 * @description btn_searchList 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_searchList_onclick = async function(e){
    try {
        await scwin.searchList()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldbnf90005.btn_searchList_onclick' }); }
};

/**
 * @method
 * @name grd_indList_oncellclick
 * @description grd_indList 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_indList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_indList');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_indList */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        scwin.selectedCorp(r["cdId"], r["cdVal"]); return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_indList.oncellclick' });
    }
};

/**
 * @method
 * @name btn_self_onclick
 * @description btn_self 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_self_onclick = function(e){
    try {
        $c.win.closePopup()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf90005.btn_self_onclick' }); }
};

/**
 * @method
 * @name __on_enter_1_ipt_searchword
 * @description on enter 1 ipt searchword 처리
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.__on_enter_1_ipt_searchword = async function(e){
    try {
        const ev = e;
        if(($c.util.getKeyCode(ev))===13){ await scwin.searchList() }

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldbnf90005.__on_enter_1_ipt_searchWord' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_searchList
 * @description search List 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_searchList = async function () {
    const sbmOptions = {
        id: "tx_fn_searchList",
        method: "post",
        action: "/common/InstSearch.do",
        ref: "dma_searchListReq",
        target: "dlt_indList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name selectedCorp
 * @description selected Corp 처리
 * @param {*} co_cd co_cd
 * @param {*} co_nm co_nm
 * @returns {void}
 * @hidden N
 */
scwin.selectedCorp = function (co_cd, co_nm) {
    const fm = (document.InputForm || { elements: [] });
    if ($c.str.getByteLength($c.util.getComponent('dma_searchListReq').get('itemCd')) > 0) {
        ((scwin.opener().getComponentById($c.util.getComponent('dma_searchListReq').get('itemCd'))) || { setValue: function () {} }).setValue(co_cd);
    }
    if ($c.str.getByteLength($c.util.getComponent('dma_searchListReq').get('itemNm')) > 0) {
        ((scwin.opener().getComponentById($c.util.getComponent('dma_searchListReq').get('itemNm'))) || { setValue: function () {} }).setValue(co_nm);
    }
    $c.win.closePopup();
};

/**
 * @method
 * @name searchList
 * @description search List 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchList = async function () {
    const fm = (document.InputForm || { elements: [] });
    if ($c.str.getByteLength($c.util.getComponent('ipt_searchWord').getValue()) === 0) {
        await $c.win.alert('검색조건을 입력바랍니다.');
    } else {
        $c.util.getComponent('ipt_method').setValue("loadSalesIndSearchData");
        fm.action = "/common/InstSearch.do";
        await scwin.tx_fn_searchList();
    }
};

/**
 * @method
 * @name opener
 * @description 부모 화면 scope(browserPopup/pageFramePopup 공통 — $c.win.getOpenerScope). 단독 진입이거나 부모가 닫혀 없으면
 * @returns {Object} 부모 화면 scope 또는 빈 scope
 * @hidden N
 */
scwin.opener = function () {
    const scope = ($c.win && $c.win.getOpenerScope) ? $c.win.getOpenerScope() : null;
    return scope || { getComponentById: function () { return null; }, scwin: {} };
};
